def require(condition, message):
    if not condition:
        raise ValueError(message)


def load(path):
    def reject(value):
        raise ValueError('Nonfinite JSON: '+value)
    return json.loads(Path(path).read_text(encoding='utf-8'), parse_constant=reject)


def canonical(value):
    return json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False)


def object_sha(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def contract_sha(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()


def file_sha(path):
    digest=hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda:stream.read(8*1024*1024),b''):
            digest.update(block)
    return digest.hexdigest()


def integer_list(value, length=None, minimum=0):
    return (isinstance(value,list) and (length is None or len(value)==length)
            and all(type(n) is int and n>=minimum for n in value))


def descriptive(values):
    return dict(n=len(values),minimum=min(values),mean=statistics.fmean(values),maximum=max(values))


class Audit:
    def __init__(self,repo,root,legacy,limit):
        self.repo,self.root,self.legacy,self.limit=repo,root,legacy,limit
        self.hashes,self.issues={},[]
        self.result=dict(schema_version=1,status='failed',budget_policy=POLICY,
            generated_utc=datetime.now(timezone.utc).isoformat(),run_root=str(root),
            expected_new_generations=2*limit,expected_cases=2,expected_doc_ids=[0,limit-1],
            frozen_source_commit=FROZEN_COMMIT,auditor_path=str(Path(__file__).resolve()),
            auditor_sha256=file_sha(__file__),cases={})

    def hash_matches(self,path,expected):
        path=Path(path).resolve()
        require(isinstance(expected,str) and HEX.fullmatch(expected),'Malformed expected SHA')
        if path not in self.hashes:self.hashes[path]=file_sha(path)
        require(self.hashes[path]==expected,'SHA mismatch: '+str(path))

    def guard(self,label,operation):
        try:return operation()
        except (OSError,ValueError,TypeError,KeyError,IndexError,ArithmeticError,ImportError) as error:
            self.issues.append(dict(check=label,error=f'{type(error).__name__}: {error}'))
            return None

    def source_check(self):
        for relative,digest in FROZEN['sources_sha256'].items():
            self.hash_matches(self.repo/relative,digest)
        require(FROZEN['sources_sha256']['src/kvrepack/baseline_utils.py']==CORE_SHA,
                'Auditor was not prepared against the reviewed v2 core')
        self.result['frozen_sources']=dict(status='passed',files=len(FROZEN['sources_sha256']),
            core_sha256=CORE_SHA,preparation=FROZEN['preparation'],
            scope='Frozen code hashes, not current HEAD: later documentation commits do not change this source identity.')

    def controller(self):
        state=load(self.root/'lookm_state.json');spec=state['spec']
        require(state['status']=='complete' and state['completed_tasks']==list(TASKS),
                'Both requested tasks and reports must complete before the final audit')
        require(spec['method']=='lookm' and spec['tasks']==list(TASKS) and spec['limit']==self.limit
                and spec['budget_ratio']==.1 and spec['budget_policy']==POLICY,'Wrong controller specification')
        self.result['controller']=dict(status='complete',path=str(self.root/'lookm_state.json'),
            sha256=file_sha(self.root/'lookm_state.json'),spec=spec)

    def header(self,task):
        case=self.root/task;c=load(case/'run_contract.json');config=load(case/'run_config.json')
        state=load(case/'run_state.json');identity=contract_sha(c);data=FROZEN['datasets'][task]
        require(c['schema_version']==1 and c['method']=='lookm' and c['task']==task
                and c['budget_policy']==POLICY and c['target_docs']==c['target_generations']==self.limit,
                'Missing strict-v2 contract or wrong task/target')
        require(state['status']=='complete' and state['completed_docs']==state['completed_generations']==self.limit
                and state['target_docs']==state['target_generations']==self.limit
                and state['contract_sha256']==identity,'Task has not completed its exact original prefix')
        require(c['frames']==64 and c['min_pixels']==200704 and c['max_pixels']==1605632
                and c['budget_ratio']==.1 and c['model_seed']==42 and c['dtype']=='bfloat16'
                and c['attention']=='flash_attention_2' and c['do_sample'] is False
                and c['use_cache'] is True and c['repetition_penalty']==1.05
                and c['max_new_tokens']==(128 if task==TASKS[0] else 64),'Wrong fixed generation profile')
        require(c['algorithm_env']=={'BUDGET':'1024','BUDGET_RATIO':'0.1','RATIO':'0.1'},
                'Algorithm environment contamination or unexpected LookM defaults')
        require(c['model_metadata']==FROZEN['model_metadata'],'Model/tokenizer metadata declarations drifted')
        for name,digest in c['model_metadata'].items():self.hash_matches(Path(c['model_snapshot'])/name,digest)
        require(Path(c['model_snapshot']).name=='cc594898137f460bfe9f0759e9844b3ce807cfb5',
                'Unexpected7B snapshot identity')
        model=load(Path(c['model_snapshot'])/'config.json');model=model.get('text_config',model)
        require((model['num_hidden_layers'],model['num_key_value_heads'],
                 model.get('head_dim',model['hidden_size']//model['num_attention_heads']))==(LAYERS,HEADS,DIM),
                'Unexpected native7B KV layout')
        for path,digest in c['sources_sha256'].items():
            relative=Path(path).resolve().relative_to(self.repo).as_posix()
            require(FROZEN['sources_sha256'].get(relative)==digest,'Run source differs from frozen source: '+relative)
            self.hash_matches(path,digest)
        require(c['sources_sha256'].get(str(self.repo/'src/kvrepack/baseline_utils.py'))==CORE_SHA,
                'Row source is the legacy core instead of reviewed v2')
        require(c['arrow_sha256']==data['arrow_sha256'] and c['dataset_rows']==data['split_rows'],
                'Wrong dataset split/Arrow identity')
        self.hash_matches(c['arrow_path'],data['arrow_sha256'])
        folder=self.repo/'vendor/lmms-eval/lmms_eval/tasks'/('nextqa' if task==TASKS[0] else 'vatex')
        for name,field in [(task+'.yaml','task_yaml_sha256'),('utils.py','task_utils_sha256')]:
            require(c[field]==data[field],'Task source declaration changed')
            self.hash_matches(folder/name,c[field])
        if c.get('included_yaml_sha256'):
            match=re.search(r'^include:\s*[\'\"]?([^\s\'\"]+)',(folder/(task+'.yaml')).read_text(),re.MULTILINE)
            require(match is not None and c['included_yaml_sha256']==data['included_yaml_sha256'],
                    'Included task YAML mismatch')
            self.hash_matches(folder/match[1],c['included_yaml_sha256'])
        for name,version in c['versions'].items():
            require(importlib.metadata.version(name)==version,'Installed generation dependency changed: '+name)
        require(config['stream_contract_sha256']==identity and config['source_files']==c['sources_sha256'],
                'Resolved config source/contract mismatch')
        for key in ('method','task','model_snapshot','frames','budget_ratio','algorithm_env','min_pixels','max_pixels',
                    'dtype','attention','model_seed','max_new_tokens','do_sample','use_cache','repetition_penalty','budget_policy'):
            require(config[key]==c[key],'Resolved configuration drift: '+key)
        generation=config['generation_overrides']
        require(generation['do_sample'] is False and generation['use_cache'] is True
                and generation['num_beams']==1 and generation['repetition_penalty']==1.05
                and generation['max_new_tokens']==c['max_new_tokens']
                and generation['eos_token_id']==151645,'Unexpected effective generation overrides')
        return c,config,identity

    def row(self,row,task,doc,contract,config,identity):
        require(row['schema_version']==1 and row['status']=='completed' and row['method']=='lookm'
                and row['task']==task and row['doc_id']==doc and row['contract_sha256']==identity
                and row['config']==config,'New sample identity/config mismatch; legacy rows cannot be reused')
        n=row['input_tokens'];require(type(n) is int and n>0,'Invalid input length')
        capacity=math.floor(n*.1);window=min(32,capacity);history=capacity-window
        require(capacity>0 and row['input_shapes']['input_ids']==[1,n],'Invalid exact input shape/capacity')
        fp=row['input_fingerprints']
        require(set(fp)=={'input_hashes','input_shapes','input_dtypes'} and
                set(fp['input_hashes'])==set(fp['input_shapes'])==set(fp['input_dtypes']), 'Bad actual input fingerprint keys')
        for field in fp:require(row[field]==fp[field],'Duplicate input fingerprint changed')
        require(all(isinstance(x,str) and HEX.fullmatch(x) for x in fp['input_hashes'].values()),'Bad actual input SHA')
        meta=row['reference_metadata'];expected=FROZEN['datasets'][task]['rows'][doc]
        require(meta['original_row_sha256']==expected['row_sha256'] and meta['video_id']==expected['video_id']
                and meta['source_video_id']==expected['source_video_id'] and meta['doc_id']==doc
                and meta['task']==task and meta['input_tokens']==n
                and row['video_id']==meta['video_id'] and row['source_video_id']==meta['source_video_id'],
                'Original cached Arrow row/video identity differs')
        for field in ('arrow_sha256','task_yaml_sha256','task_utils_sha256'):
            require(meta[field]==contract[field],'Row data/task source SHA drift')
        frames=meta['frame_sampling'];indices=frames['selected_indices']
        require(frames['requested_frames']==frames['selected_frames']==64 and integer_list(indices,64)
                and len(set(indices))==frames['unique_frames']
                and 64-len(set(indices))==frames['repeated_frames'],'Frame sampling record inconsistent')
        ids=row['generated_ids'];cap=contract['max_new_tokens'];eos=row['eos_token_id']
        require(integer_list(ids,minimum=0) and 0<len(ids)<=cap and row['generated_tokens']==len(ids)
                and row['max_new_tokens']==cap and row['text']==row['prediction']
                and isinstance(row['text'],str) and eos==config['generation_overrides']['eos_token_id']
                and row['eos_reached']==(ids[-1]==eos) and eos not in ids[:-1],'Generation/EOS/cap record inconsistent')
        cache=row['cache_audit'];require(row['audit']==cache,'Duplicate native cache audits differ')
        require(cache['status']=='completed' and cache['budget_policy']==POLICY and cache['strict_budget_passed'] is True
                and cache['total_prefill_capacity']==capacity and cache['method']=='lookm'
                and cache['task']==task and cache['doc_id']==doc and cache['input_tokens']==n
                and cache['native_kv_heads']==HEADS and cache['layers_count']==LAYERS
                and cache['nominal_budget_ratio']==.1,'Wrong strict-v2 cache policy/identity')
        require([x['layer'] for x in cache['layers']]==list(range(LAYERS)) and
                [x['layer'] for x in row['final_cache_shapes']]==list(range(LAYERS)),'Missing/duplicate actual cache layer')
        for layer,final in zip(cache['layers'],row['final_cache_shapes']):
            require(layer['before_tokens_per_head']==n and layer['head_lengths']==[capacity]*HEADS
                    and layer['selected_history_tokens']==history and layer['recent_window']==window
                    and layer['configured_recent_window']==32 and layer['total_prefill_capacity']==capacity
                    and layer['native_budget_ratio']==.1,'Wrong history/recent/total capacity in a native head')
            require(layer['key_shape']==layer['value_shape']==[1,HEADS,capacity,DIM]
                    and final['key_shape']==final['value_shape']==[1,HEADS,capacity+len(ids)-1,DIM]
                    and layer['after_tokens_total']==HEADS*capacity
                    and layer['final_tokens_total']==HEADS*(capacity+len(ids)-1)
                    and layer['decode_added_tokens_per_head']==len(ids)-1,
                    'Actual prefill/final shapes fail independent G-1 decode subtraction')
            require(layer['key_dtype']==layer['value_dtype']==final['key_dtype']==final['value_dtype']=='torch.bfloat16',
                    'Actual native cache dtype changed')
        total=LAYERS*HEADS*capacity;denom=LAYERS*HEADS*n;ratio=total/denom
        require(cache['prefill_tokens_total']==total and cache['uncompressed_tokens_total']==denom
                and cache['actual_retained_ratio']==ratio and ratio<=.1,'Strict total prefill ratio exceeds10% or is mislabeled')
        return dict(doc_id=doc,N=n,C=capacity,history=history,window=window,ratio=ratio,slots=total,
            generated_tokens=len(ids),eos=row['eos_reached'],at_cap=len(ids)==cap,
            cache_audit_sha256=object_sha(cache))

    def report(self,task,contract,config,identity,stats,files):
        path=self.root/task/'report/summary.json';summary=load(path);provenance=summary['provenance']
        require(summary['status']=='complete' and summary['task']==task and summary['method']=='lookm'
                and summary['limit']==summary['n_generations']==self.limit
                and summary['budget_policy']==POLICY and summary['strict_budget_passed'] is True
                and summary['legacy_budget_result'] is False and summary['formal_result']==(self.limit==200)
                and summary['sample_scope']==('original_first200' if self.limit==200 else 'smoke_first1'),
                'Report scope/policy/completion mismatch')
        require(provenance['generation_contract']==contract and provenance['config']==config
                and provenance['contract_sha256']==identity,'Report not bound to these new strict generations')
        self.hash_matches(self.root/task/'run_contract.json',provenance['contract_file_sha256'])
        self.hash_matches(self.root/task/'run_state.json',provenance['state_file_sha256'])
        require(provenance['sample_files']==files,'Report sample paths/SHA differ from the independently streamed files')
        ref=provenance['reference'];data=FROZEN['datasets'][task]
        require(ref['sha256']==data['arrow_sha256'] and ref['split_rows']==data['split_rows']
                and ref['selected_rows']==self.limit and ref['doc_ids']==list(range(self.limit))
                and ref['selected_reference_rows_sha256']==data['selected_reference_rows_sha256'][str(self.limit)],
                'Scoring references differ from independently read frozen Arrow prefix')
        require(provenance['scoring_source_sha256']==FROZEN['sources_sha256']['src/kvrepack/benchmarks/single_video_report.py'],
                'Report used different scorer entry source')
        self.hash_matches(provenance['helper_path'],provenance['helper_sha256'])
        self.hash_matches(provenance['task_scorer']['path'],provenance['task_scorer']['source_sha256'])
        if task==TASKS[0]:self.hash_matches(self.repo/'vendor/lmms-eval/lmms_eval/tasks/nextqa/stopwords.csv',provenance['stopwords_sha256'])
        if provenance.get('local_caption_resources_sha256'):
            dist=importlib.metadata.distribution('pycocoevalcap')
            for relative,digest in provenance['local_caption_resources_sha256'].items():self.hash_matches(dist.locate_file(relative),digest)
        for name,version in provenance['dependency_versions'].items():
            require(importlib.metadata.version(name)==version,'Installed score dependency changed: '+name)
        generation=dict(n_inputs=self.limit,eos_count=sum(x['eos'] for x in stats),
            reached_length_limit=sum(x['at_cap'] for x in stats),
            capped_without_eos=sum(x['at_cap'] and not x['eos'] for x in stats),
            generated_tokens_min=min(x['generated_tokens'] for x in stats),
            generated_tokens_max=max(x['generated_tokens'] for x in stats),
            generated_tokens_mean=statistics.fmean(x['generated_tokens'] for x in stats))
        require(summary['generation']==generation,'Report generation statistics disagree with raw records')
        budget=summary['cache_budget'];ratios=[x['ratio'] for x in stats]
        require(budget['budget_policy']==POLICY and budget['strict_budget_passed'] is True
                and budget['legacy_budget_result'] is False and budget['configured_budget_ratio']==.1
                and budget['actual_retained_ratio_min']==min(ratios)
                and budget['actual_retained_ratio_mean']==statistics.fmean(ratios)
                and budget['actual_retained_ratio_max']==max(ratios),'Report cache statistics disagree with raw records')
        with (path.parent/'cache_audit.csv').open(newline='') as f:cache_rows=list(csv.DictReader(f))
        require(len(cache_rows)==self.limit,'Report cache CSV count differs')
        for saved,actual in zip(cache_rows,stats):
            require(int(saved['doc_id'])==actual['doc_id'] and saved['cache_audit_sha256']==actual['cache_audit_sha256']
                    and saved['budget_policy']==POLICY and saved['strict_budget_passed']=='True',
                    'Report per-input cache CSV differs')
        metrics=summary['metrics'];expected={'WUPS'} if task==TASKS[0] else {'Bleu_4','METEOR','ROUGE_L','CIDEr'}
        require(set(metrics)==expected and all(type(v) in (int,float) and math.isfinite(v) for v in metrics.values()),
                'Missing or nonfinite native metric metadata')
        return dict(status='passed',path=str(path),sha256=file_sha(path),metrics_as_recorded=metrics,
            score_values_not_recomputed=True,scoring_reference_prefix_verified=True,generation=generation)

    def case(self,task):
        contract,config,identity=self.header(task);case=self.root/task
        paths=sorted((case/'samples').glob('*.json'))
        require([p.name for p in paths]==[f'{i:06d}.json' for i in range(self.limit)],'Missing/extra/duplicate original prefix samples')
        legacy=self.legacy/'lookm'/task;old_contract=load(legacy/'run_contract.json')
        require(old_contract.get('budget_policy')!=POLICY,'Legacy comparison source is incorrectly labeled strict-v2')
        stats=[];files=[];changed_text=[];changed_ids=[];source_videos=set();before_slots=[]
        for doc,path in enumerate(paths):
            raw=path.read_bytes();row=load(path);stat=self.row(row,task,doc,contract,config,identity)
            require(path.read_bytes()==raw,'Committed sample changed during audit')
            stats.append(stat);source_videos.add(row['source_video_id'])
            files.append(dict(doc_id=doc,path=str(path.resolve()),sha256=hashlib.sha256(raw).hexdigest()))
            prior=load(legacy/'samples'/f'{doc:06d}.json')
            for field in ('task','doc_id','input_hashes','input_shapes','input_dtypes','input_tokens','reference_metadata','video_id','source_video_id'):
                require(row[field]==prior[field],f'Legacy/current original input mismatch doc{doc}: '+field)
            require(prior['contract_sha256']!=identity and prior['cache_audit'].get('budget_policy')!=POLICY,
                    'Legacy sample identity appears reused as a new strict record')
            if prior['generated_ids']!=row['generated_ids']:changed_ids.append(doc)
            if prior['text']!=row['text']:changed_text.append(doc)
            before_slots.append(prior['cache_audit']['prefill_tokens_total'])
        report=self.report(task,contract,config,identity,stats,files)
        return dict(status='passed',new_generations=len(paths),doc_ids=[0,self.limit-1],
            native_prefill_layer_captures=LAYERS*self.limit,native_prefill_head_captures=LAYERS*HEADS*self.limit,
            source_video_clusters=len(source_videos),input_tokens=descriptive([x['N'] for x in stats]),
            total_prefill_capacity_per_head=descriptive([x['C'] for x in stats]),
            history_topk=descriptive([x['history'] for x in stats]),recent_window_histogram=dict(Counter(x['window'] for x in stats)),
            actual_prefill_ratio=descriptive([x['ratio'] for x in stats]),
            generated_token_length_histogram=dict(sorted(Counter(x['generated_tokens'] for x in stats).items())),
            report_metadata_check=report,
            legacy_input_identity_check=dict(status='passed',source_root=str(legacy),paired_original_inputs=self.limit,
                new_contract_identity_differs=True,text_changed_count=len(changed_text),text_changed_doc_ids=changed_text,
                generated_ids_changed_count=len(changed_ids),generated_ids_changed_doc_ids=changed_ids,
                legacy_active_prefill_slots=descriptive(before_slots),
                current_active_prefill_slots=descriptive([x['slots'] for x in stats]),
                scope='Only input identity must match. Outputs are not expected equal. Budget, drop-mask correction and numerical/shape fixes changed together; differences cannot be attributed only to32 slots.'),
            sample_files_ordered_sha256=object_sha(files))

    def run(self):
        self.guard('frozen_sources',self.source_check);self.guard('controller_complete',self.controller)
        for task in TASKS:
            self.result['cases'][task]=self.guard(task,lambda t=task:self.case(t)) or {'status':'failed'}
        self.result.update(status='failed' if self.issues else 'passed',issues=self.issues,issue_count=len(self.issues),
            actual_new_generations=sum(x.get('new_generations',0) for x in self.result['cases'].values()),
            independently_rehashed_files=len(self.hashes),verified_files_sha256={str(p):v for p,v in sorted(self.hashes.items())})
        self.result['scope_limits']=[
            'The10% cap includes all retained prompt positions and the recent window at prefill. Generated decode K/V appends normally; finalC+G-1 can exceed10% of originalN.',
            'Model/tokenizer/config/index metadata SHA checked; multi-GB weight tensor bytes have no original contract SHA and were not independently rehashed.',
            'Original Arrow bytes and every recorded row identity/SHA checked against the frozen independently read prefix. Input tensor SHA equality is checked against legacy records; this audit does not regenerate video tensors.',
            'Full KV-value/logit bytes are not present in these records. This audit does not assert unrecorded numerical equality, rerun scores or initialize GPU.']
        return self.result


def main(argv=None):
    repo=Path(__file__).resolve().parents[2];parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo-root',type=Path,default=repo)
    parser.add_argument('--run-root',type=Path,default=repo/'outputs/benchmarks/lookm_strict_200_20261109')
    parser.add_argument('--legacy-root',type=Path,default=repo/'outputs/benchmarks/lookm_vs_kvrepack_20261109')
    parser.add_argument('--limit',type=int,choices=(1,200),default=200)
    parser.add_argument('--check-only',action='store_true')
    args=parser.parse_args(argv)
    result=Audit(args.repo_root.resolve(),args.run_root.resolve(),args.legacy_root.resolve(),args.limit).run()
    if args.check_only:print(json.dumps(result,ensure_ascii=False,indent=2,allow_nan=False))
    else:
        target=args.run_root.resolve()/'independent_execution_check.json'
        with target.open('x',encoding='utf-8') as f:
            json.dump(result,f,ensure_ascii=False,indent=2,allow_nan=False);f.write('\n')
        print(json.dumps(dict(status=result['status'],issue_count=result['issue_count'],
            new_generations=result['actual_new_generations'],output=str(target)),ensure_ascii=False))
    return 0 if result['status']=='passed' else 1


if __name__=='__main__':raise SystemExit(main())
